{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Sound Journeys & Mini-Retreats</title>
  <meta name="description" content="Playful, premium sound baths and curated mini-series to reset, restore, and re-align in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="container header-grid">
      <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="events.html">Gather</a>
        <a href="private-sessions.html">Private</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">Story</a>
        <a href="faq.html">Help</a>
        <a href="book.html" class="cta small">Book Now</a>
        <a href="contact.html">Reach</a>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero">
      <div class="pattern"></div>
      <div class="container hero-grid">
        <div class="hero-content">
          <h1 class="hug">Sonic Baths for the Modern Pause</h1>
          <p class="lead">Curated sound journeys, short series, and one-on-one sessions designed to shift mood and sharpen clarity. Gentle, playful, and thoughtfully held.</p>
          <div class="hero-actions">
            <a id="primary-cta" class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="events.html">See Upcoming</a>
          </div>
        </div>
        <aside class="hero-side">
          <div class="mood-card">
            <h4>How are you feeling?</h4>
            <!-- Mood-to-Method selector instance A -->
            <div class="mood-selector" data-instance="A">
              <button data-mood="anxious">Anxious</button>
              <button data-mood="tired">Tired</button>
              <button data-mood="wired">Wired</button>
              <button data-mood="curious">Curious</button>
            </div>
            <div class="mood-recommendation" aria-live="polite">
              <h5 class="method-title">Gentle Resonance</h5>
              <p class="method-copy">A short guided sound bath to calm nervous tension and invite soft breath work.</p>
              <a class="btn slim mood-cta" href="book.html">Reserve a spot</a>
            </div>
          </div>

          <div class="mini-stats">
            <div>
              <strong>Next</strong>
              <p class="muted">Community sink-in • Fri 7pm</p>
            </div>
            <div>
              <strong>Location</strong>
              <p class="muted">{{CITY}}, {{STATE}}</p>
            </div>
          </div>
        </aside>
      </div>
    </section>

    <section class="story container">
      <h2>We shape sound like small maps for feeling better</h2>
      <p>Short, deep, and intentionally paced gatherings that help you unwind with clarity — whether you want a weekly cadence or a weekend reset. Our offerings are cohort-based, intimate, and designed to fit real life.</p>
    </section>

    <section class="framework">
      <div class="container">
        <h3>Pick your rhythm</h3>
        <div class="grid three">
          <article>
            <h4>Pulse Circles</h4>
            <p>Weekly communal sessions—consistent, soft-touch, perfect for keeping the nervous system steady.</p>
          </article>
          <article>
            <h4>Mini-Series</h4>
            <p>4-session cohorts that build a small, supportive arc for clearer next steps.</p>
          </article>
          <article>
            <h4>Solo Lenses</h4>
            <p>One-on-one sound offerings for focused shifts and private recalibration.</p>
          </article>
        </div>

        <!-- Mood-to-Method selector instance B (repeated as requested) -->
        <div class="mood-block">
          <h4>Not sure what to choose?</h4>
          <div class="mood-selector" data-instance="B">
            <button data-mood="anxious">Anxious</button>
            <button data-mood="tired">Tired</button>
            <button data-mood="wired">Wired</button>
            <button data-mood="curious">Curious</button>
          </div>
          <div class="mood-recommendation">
            <h5 class="method-title">Mini-Series</h5>
            <p class="method-copy">A short, steady arc to build soft skills and renewed perspective.</p>
            <a class="btn slim mood-cta" href="pricing.html">See rates</a>
          </div>
        </div>
      </div>
    </section>

    <section class="offers container">
      <h3>Offerings & a playful pricing toggle</h3>
      <p class="muted">Tap between monthly support and packaged bundles. Numbers animate to show the shift.</p>

      <div class="pricing-card">
        <div class="toggle-row">
          <span class="muted">Billing:</span>
          <div class="switch" id="pricing-toggle">
            <button data-mode="monthly" class="active">Monthly</button>
            <button data-mode="package">Package</button>
          </div>
        </div>

        <div class="grid three">
          <div class="plan">
            <h4>Pulse Circle</h4>
            <div class="price" data-month="45" data-package="160">$<span class="num">45</span></div>
            <p class="muted">Weekly group session — steady support.</p>
            <a class="btn outline" href="book.html">Join a circle</a>
          </div>

          <div class="plan featured">
            <h4>Mini-Series</h4>
            <div class="price" data-month="80" data-package="280">$<span class="num">80</span></div>
            <p class="muted">Four sessions; practical resets and reflections.</p>
            <a class="btn" href="book.html">Claim a spot</a>
          </div>

          <div class="plan">
            <h4>Solo Lenses</h4>
            <div class="price" data-month="120" data-package="420">$<span class="num">120</span></div>
            <p class="muted">One-on-one recalibration with personalized sound work.</p>
            <a class="btn outline" href="private-sessions.html">Inquire</a>
          </div>
        </div>

        <p class="disclaimer">Contraindications: If you have epilepsy, recent head injury, pregnancy concerns, or active psychosis, please consult a medical professional before attending sound-based sessions. Reach out at {{EMAIL}} for specific questions.</p>
      </div>
    </section>

    <section class="testimonials container">
      <h3>What folks say</h3>
      <div class="quote-grid">
        <blockquote>
          "A warm reset — quick to settle and surprisingly deep. The cohort feel kept me coming back."
          <cite>— M. from {{CITY}}</cite>
        </blockquote>
        <blockquote>
          "Private session helped me find a steadier breath the following week. Practical and gentle."
          <cite>— J. in {{STATE}}</cite>
        </blockquote>
      </div>
    </section>

    <section class="cta container">
      <div class="cta-inner">
        <h3>Ready to try a sound session?</h3>
        <p>Spaces fill — choose a simple step below.</p>
        <div>
          <a class="btn big" href="events.html">See next gatherings</a>
          <a class="btn hollow" href="book.html">Book a private</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">Curated sound journeys in {{CITY}}, {{STATE}}.</p>
      </div>
      <div>
        <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <div>
        <p class="muted">Resources</p>
        <nav class="foot-nav">
          <a href="faq.html">Safety & Contraindications</a>
          <a href="terms.html">Terms</a>
          <a href="privacy.html">Privacy</a>
        </nav>
      </div>
    </div>
    <p class="fineprint">Disclaimer: Sound work is supportive but not a substitute for medical or psychiatric care. If you are in crisis, seek emergency services.</p>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
