{"path":"assets/css/styles.css","content":"/* Playful premium CSS — no external fonts, cohesive system */
:root{
  --bg:#0f1724; --card:#0b1220; --accent:#ffd166; --muted:#9aa6b2; --glass:rgba(255,255,255,0.04);
  --radius:12px; --joy:1.08;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:#e6eef6;background:linear-gradient(180deg,#08101a 0%,#07131a 100%)}
.container{max-width:1100px;margin:0 auto;padding:28px}
.header-grid{display:flex;align-items:center;justify-content:space-between;padding:18px 0}
.brand{font-weight:800;color:var(--accent);text-decoration:none;font-size:20px}
.nav a{color:#cfe6ff;margin-left:18px;text-decoration:none;font-weight:600}
.nav .cta{background:var(--accent);color:#07111a;padding:8px 12px;border-radius:8px}
.hero{position:relative;padding:64px 0;color:#fff}
.pattern{position:absolute;inset:0;opacity:0.08;background-image:url('../assets/img/pattern.svg');background-repeat:repeat;mix-blend-mode:screen}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:28px;align-items:start}
.hug{font-size:40px;margin:0 0 12px;line-height:1.02;letter-spacing:-0.02em}
.lead{color:var(--muted);margin:0 0 18px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:700}
.btn.primary{background:var(--accent);color:#07111a}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:#cfe6ff}
.btn.big{padding:12px 18px;font-size:16px}
.btn.hollow{border:2px solid rgba(255,255,255,0.06);background:transparent;color:#fff}
.btn.slim{padding:8px 10px}
.hero-side{position:relative}
.mood-card{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:16px;border-radius:14px;border:1px solid rgba(255,255,255,0.03)}
.mood-selector{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}
.mood-selector button{background:var(--glass);border:1px solid rgba(255,255,255,0.03);color:#dff;padding:8px 10px;border-radius:8px;cursor:pointer}
.mood-recommendation{margin-top:10px}
.method-title{margin:0 0 6px}
.method-copy{color:var(--muted);margin:0 0 8px}
.mini-stats{display:flex;gap:12px;margin-top:12px}
.mini-stats .muted{color:var(--muted)}
.story{padding:34px 28px}
.framework{background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:34px 0}
.grid.three{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.grid.three article{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.02)}
.mood-block{margin-top:22px}
.pricing-card{background:linear-gradient(180deg,rgba(255,255,255,0.01),rgba(255,255,255,0.005));padding:20px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
.toggle-row{display:flex;align-items:center;gap:10px;margin-bottom:14px}
.switch{background:rgba(255,255,255,0.03);padding:6px;border-radius:999px;display:inline-flex}
.switch button{background:transparent;border:0;padding:8px 12px;color:#dff;border-radius:999px;cursor:pointer}
.switch button.active{background:var(--accent);color:#07111a}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.plan{background:#071320;padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.02);text-align:center}
.plan.featured{transform:translateY(-8px);box-shadow:0 8px 30px rgba(0,0,0,0.6)}
.price{font-size:28px;font-weight:800;margin:8px 0}
.num{display:inline-block;min-width:32px;text-align:right}
.disclaimer{font-size:12px;color:var(--muted);margin-top:12px}
.testimonials{padding:28px 0}
.quote-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}
blockquote{background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.02)}
.site-footer{padding:28px 0;border-top:1px solid rgba(255,255,255,0.03);margin-top:40px}
.footer-grid{display:flex;justify-content:space-between;gap:10px}
.muted{color:var(--muted)}
.fineprint{font-size:12px;color:var(--muted);margin-top:12px}
@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .grid.three{grid-template-columns:1fr}
  .grid{grid-template-columns:1fr}
  .footer-grid{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"// Main JS for interactive micro-widgets
(function(){
  // Utility: animate numbers
  function animateValue(el, start, end, duration){
    var startTime = null;
    var step = function(timestamp){
      if(!startTime) startTime = timestamp;
      var progress = Math.min((timestamp - startTime)/duration, 1);
      var value = Math.floor(start + (end - start) * progress);
      el.textContent = value;
      if(progress < 1) window.requestAnimationFrame(step);
    };
    window.requestAnimationFrame(step);
  }

  // Pricing toggle logic
  var toggle = document.getElementById('pricing-toggle');
  if(toggle){
    toggle.addEventListener('click', function(e){
      var btn = e.target.closest('button');
      if(!btn) return;
      var mode = btn.getAttribute('data-mode');
      // set active state
      Array.from(toggle.querySelectorAll('button')).forEach(function(b){b.classList.toggle('active', b===btn)});
      // for each price, animate
      Array.from(document.querySelectorAll('.price')).forEach(function(p){
        var numEl = p.querySelector('.num');
        var from = parseInt(numEl.textContent,10) || 0;
        var to = parseInt(p.getAttribute(mode==='package'?'data-package':'data-month'),10) || from;
        animateValue(numEl, from, to, 500);
      });
    });
  }

  // Mood-to-Method selector logic (works for multiple instances)
  function setupMoodSelectors(){
    var mapping = {
      anxious:{title:'Gentle Resonance',copy:'Short guided bath to ease tension; focus on long exhale and soft tones.',ctaText:'Book a calming slot',ctaHref:'book.html'},
      tired:{title:'Slow Restore',copy:'A quieter, slower sequence aimed at restful reset and slowed nervous system.',ctaText:'Claim a slow session',ctaHref:'events.html'},
      wired:{title:'Ground & Settle',copy:'Rhythmic low tones and breath anchors to steady energy and focus.',ctaText:'Try a grounding session',ctaHref:'book.html'},
      curious:{title:'Explore Series',copy:'A mini-series to learn tools and notice sustainable change.',ctaText:'See the mini-series',ctaHref:'pricing.html'}
    };

    Array.from(document.querySelectorAll('.mood-selector')).forEach(function(wrapper){
      wrapper.addEventListener('click', function(e){
        var btn = e.target.closest('button');
        if(!btn) return;
        var mood = btn.getAttribute('data-mood');
        var rec = wrapper.parentElement.querySelector('.mood-recommendation');
        var title = rec.querySelector('.method-title');
        var copy = rec.querySelector('.method-copy');
        var cta = rec.querySelector('.mood-cta');
        var map = mapping[mood] || mapping['curious'];
        // little morph animation
        title.style.opacity = 0; copy.style.opacity = 0; cta.style.opacity = 0;
        setTimeout(function(){
          title.textContent = map.title;
          copy.textContent = map.copy;
          if(cta){ cta.textContent = map.ctaText; cta.setAttribute('href', map.ctaHref); }
          title.style.opacity = 1; copy.style.opacity = 1; if(cta) cta.style.opacity = 1;
        }, 120);
      });
    });
  }
  setupMoodSelectors();

  // Small UX: initialize pricing numbers to monthly values
  document.addEventListener('DOMContentLoaded', function(){
    Array.from(document.querySelectorAll('.price')).forEach(function(p){
      var numEl = p.querySelector('.num');
      var val = p.getAttribute('data-month') || numEl.textContent;
      numEl.textContent = val;
    });
  });

})();"} 
